const config = $json;
const queries = String(config.queries ?? '')
  .split(/\r?\n/)
  .map((query) => query.trim())
  .filter(Boolean);

if (queries.length === 0) {
  throw new Error('Add at least one query to Monitoring Configuration.');
}
if (!String(config.trackedBrand ?? '').trim()) {
  throw new Error('trackedBrand is required.');
}
if (!String(config.trackedDomain ?? '').trim()) {
  throw new Error('trackedDomain is required.');
}

return queries.map((query, index) => ({
  json: {
    ...config,
    query,
    queryIndex: index + 1,
    totalQueries: queries.length,
    googleUrl: `https://www.google.com/search?q=${encodeURIComponent(query)}`
  }
}));

const job = $('Prepare Search Jobs').item.json;
const payload = $json.data ?? $json;
const structured = payload.json ?? payload.data?.json ?? payload;
const entries = Array.isArray(structured.items) ? structured.items : [];
const aiOverview = entries.find((entry) => entry?.type === 'ai_overview')
  ?? structured.ai_overview
  ?? structured.aiOverview
  ?? null;
const references = Array.isArray(aiOverview?.references)
  ? aiOverview.references
  : Array.isArray(structured.references) ? structured.references : [];
const organicResults = entries.flatMap((entry) => {
  if (entry?.type !== 'organic') return [];
  return Array.isArray(entry.items) ? entry.items : [entry];
});

const brand = String(job.trackedBrand).trim().toLowerCase();
const domain = String(job.trackedDomain).trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '');
const searchableText = JSON.stringify({ aiOverview, references, organicResults }).toLowerCase();
const brandMentioned = searchableText.includes(brand);
const targetDomainCited = references.some((reference) => String(reference?.url ?? reference?.link ?? '').toLowerCase().includes(domain));
const organicPositionIndex = organicResults.findIndex((result) => String(result?.url ?? result?.link ?? '').toLowerCase().includes(domain));
const organicPosition = organicPositionIndex >= 0 ? organicPositionIndex + 1 : null;
const hasAiOverview = Boolean(aiOverview);
const withinOrganicLimit = organicPosition !== null && organicPosition <= Number(job.maxOrganicPosition);
const visibilityScore = (brandMentioned ? 40 : 0) + (targetDomainCited ? 35 : 0) + (hasAiOverview ? 15 : 0) + (withinOrganicLimit ? 10 : 0);
const alertReasons = [];
if (!hasAiOverview) alertReasons.push('No AI Overview detected');
if (!brandMentioned) alertReasons.push(`Brand not mentioned: ${job.trackedBrand}`);
if (!targetDomainCited) alertReasons.push(`Domain not cited: ${job.trackedDomain}`);
if (!withinOrganicLimit) alertReasons.push(`Domain not in top ${job.maxOrganicPosition} organic results`);

return {
  json: {
    checkedAt: new Date().toISOString(),
    query: job.query,
    googleUrl: job.googleUrl,
    trackedBrand: job.trackedBrand,
    trackedDomain: job.trackedDomain,
    minimumVisibilityScore: Number(job.minimumVisibilityScore),
    maxOrganicPosition: Number(job.maxOrganicPosition),
    alertFromEmail: job.alertFromEmail,
    alertToEmail: job.alertToEmail,
    taskId: payload.taskId ?? payload.task_id ?? null,
    hasAiOverview,
    brandMentioned,
    targetDomainCited,
    citationCount: references.length,
    organicResultCount: organicResults.length,
    organicPosition,
    visibilityScore,
    alertReasons,
    aiOverview,
    references,
    organicResults,
    screenshot: payload.screenshot ?? null,
    productUrl: 'https://www.pangolinfo.com/ai-overview-serp-api/'
  }
};

const results = $input.all().map((item) => item.json);
if (results.length === 0) throw new Error('No visibility results were returned.');

const rankedResults = [...results].sort((a, b) => a.visibilityScore - b.visibilityScore);
const averageVisibilityScore = Math.round(results.reduce((sum, row) => sum + row.visibilityScore, 0) / results.length);
const issueResults = rankedResults.filter((row) => row.alertReasons.length > 0);
const minimumVisibilityScore = Number(results[0].minimumVisibilityScore);
const alertRequired = issueResults.length > 0 || averageVisibilityScore < minimumVisibilityScore;
const reportRows = rankedResults.map((row) => {
  const position = row.organicPosition ?? 'not found';
  const status = row.alertReasons.length ? `ATTENTION: ${row.alertReasons.join('; ')}` : 'Healthy';
  return `| ${row.query} | ${row.visibilityScore} | ${row.citationCount} | ${position} | ${status} |`;
});
const reportMarkdown = [
  '# Google AI Overview visibility report',
  '',
  `Checked: ${new Date().toISOString()}`,
  `Queries: ${results.length}`,
  `Average visibility score: ${averageVisibilityScore}/100`,
  `Queries requiring attention: ${issueResults.length}`,
  '',
  '| Query | Score | Citations | Organic position | Status |',
  '| --- | ---: | ---: | ---: | --- |',
  ...reportRows,
  '',
  'Scoring: brand mention 40, target-domain citation 35, AI Overview present 15, acceptable organic position 10.',
  '',
  'Product: https://www.pangolinfo.com/ai-overview-serp-api/'
].join('\n');

return [{ json: {
  checkedAt: new Date().toISOString(),
  alertRequired,
  queryCount: results.length,
  issueCount: issueResults.length,
  averageVisibilityScore,
  minimumVisibilityScore,
  alertFromEmail: results[0].alertFromEmail,
  alertToEmail: results[0].alertToEmail,
  alertSubject: `[GEO Alert] ${issueResults.length} of ${results.length} queries need attention`,
  alertText: reportMarkdown,
  reportMarkdown,
  issueResults,
  results
} }];
